mapper.select:
SELECT

FROM SnsPostComment a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.postId = #{postId}


    AND a.commentUserId = #{commentUserId}


    AND a.commentContent LIKE CONCAT('%',#{commentContent}, '%')


    AND a.commentLikeNum = #{commentLikeNum}


    AND a.replyTo LIKE CONCAT('%',#{replyTo}, '%')


    AND a.lng LIKE CONCAT('%',#{lng}, '%')


    AND a.lat LIKE CONCAT('%',#{lat}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.isRead = #{isRead}


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

select aa.remark as remark, aa.id as id , aa.postId as postId, aa.postUserId as postUserId, aa.userId, aa.commentUserId, aa.commentLikeNum, aa.commentContent, aa.topCommentContent as topCommentContent, aa.createTime as createTime, aa.isLike, cc.accountName as commentAccountName, cc.headUrl as commentHeadUrl, ifnull(aa.topUserId,bb.userId) as topUserId, aa.cnt > 0 as hasSubComments, aa.cnt as subCommentsCnt, ifnull(dd.accountName,bb.accountName) as topUserAccountName, ifnull(dd.headUrl,bb.headUrl) as topUserHeadUrl from Account bb,Account cc, ( select a.remark, a.id, a.postId, a.userId as userId, b.userId as postUserId, a.commentUserId as commentUserId, a.commentLikeNum as commentLikeNum, a.commentContent as commentContent, a.createTime as createTime, b.commentUserId as topUserId , b.commentContent as topCommentContent, (select count(*) from SnsPostComment b where b.replyTo = a.id) as cnt, case when #{viewerUserId} is null then 0 else (select count(*) from SnsPostCommentLike l where l.postId = a.postId and l.postCommentId=a.id and l.likeUserId = #{viewerUserId} )>0 end as isLike from SnsPostComment a left join SnsPostComment b on a.replyTo = b.id where a.postId = #{postId}
and a.replyTo = #{commentId}
and (a.replyTo is null or a.replyTo = '')
) aa left join Account dd on aa.topUserId = dd.userId where aa.userId = bb.userId and aa.commentUserId = cc.userId

select aa.id as id , aa.remark as remark, aa.postId as postId, aa.postUserId as postUserId, aa.postUserHeadUrl as postUserHeadUrl, aa.postUserAccountName as postUserAccountName, aa.userId, aa.commentUserId, aa.commentLikeNum, aa.topCommentContent as topCommentContent, aa.commentContent, aa.createTime as createTime, aa.isLike, aa.isRead as isRead, aa.openness as openness, aa.postTextContent as postTextContent, aa.postImageUrl as postImageUrl, aa.viewer as viewer, (case when aa.openness=0 then '' else cc.accountName end) as commentAccountName, (case when aa.openness=0 then '' else cc.headUrl end) as commentHeadUrl, ifnull(aa.topUserId,bb.userId) as topUserId, aa.cnt > 0 as hasSubComments, aa.cnt as subCommentsCnt, (case when aa.openness=0 then '' else ifnull(dd.accountName,bb.accountName) end) as topUserAccountName, (case when aa.openness=0 then '' else ifnull(dd.headUrl,bb.headUrl) end) as topUserHeadUrl from Account bb,Account cc, ( select p.openness as openness, p.postTextContent as postTextContent, p.postImageUrl as postImageUrl, p.viewer as viewer, a.id, a.remark, a.postId, a.userId as userId, b.userId as postUserId, pa.accountName as postUserAccountName, pa.headUrl as postUserHeadUrl, a.commentUserId as commentUserId, a.commentLikeNum as commentLikeNum, a.commentContent as commentContent, a.createTime as createTime, b.commentUserId as topUserId , b.commentContent as topCommentContent, a.isRead as isRead, (select count(*) from SnsPostComment b where b.replyTo = a.id) as cnt, 0 as isLike from SnsPost p,Account pa,SnsPostComment a left join SnsPostComment b on a.replyTo = b.id where p.userId = #{userId} and p.userId = pa.userId and p.id = a.postId and p.openness != 0
and a.isRead = #{isRead}
) aa left join Account dd on aa.topUserId = dd.userId where aa.userId = bb.userId and aa.commentUserId = cc.userId
